'use client';

import { useCallback, useEffect, useState } from 'react';
import { LingxiTrackLive } from './lingxi-track';

declare global { interface Window { XLSX?: { read: (data: ArrayBuffer) => { SheetNames: string[]; Sheets: Record<string, unknown> }; utils: { sheet_to_json: (sheet: unknown, options?: Record<string, unknown>) => Record<string, unknown>[] } } } }
type Pipeline = { id: string; name: string; targetCount: number; deliveredCount: number; budget: number; spent: number };
type KeyComment = { id: string; noteId: string; content: string; author: string; sentiment: string; category: string; action: string; treatmentStatus: string; treatmentMethod?: string; lastSeenAt: string; disappearedAt?: string; replyCount: number };
type Note = { id: string; url: string; author: string; title: string; sourceType: string; pipeline: string; level: string; productScope: string; publishedAt?: string; lastFetchedAt?: string; commentTotal: number; positiveCount: number; negativeCount: number; questionCount: number; brandMentionTop5: number; status: string; coverUrl?: string; category1?: string; category2?: string; cooperation?: number; promoted?: number; noteType?: string; notePrice?: number; exposure?: number; readCount?: number; interactionCount?: number; likeCount?: number; favoriteCount?: number; shareCount?: number; fansCount?: number; creatorLevel?: string; province?: string; city?: string; gender?: string; brand?: string; cpm?: number; cpr?: number; cpe?: number; engagementRate?: number };
type AnalyticRow = Record<string, string | number | null>;
type Analytics = { trend: AnalyticRow[]; sourceDistribution: AnalyticRow[]; scopeDistribution: AnalyticRow[]; statusDistribution: AnalyticRow[]; topics: AnalyticRow[]; brands: AnalyticRow[]; formats: AnalyticRow[]; creatorLevels: AnalyticRow[]; categories: AnalyticRow[]; locations: AnalyticRow[]; dataQuality: AnalyticRow; topNotes: AnalyticRow[] };
type Dashboard = { projectId?:string; pipelines: Pipeline[]; metrics: { noteCount: number; commentTotal: number; positiveCount: number; positiveRate: number; negativeCount: number; negativeRate: number; questionCount: number; questionRate: number; neutralCount?: number; exposure?: number; readCount?: number; interactionCount?: number; creatorCost?: number; promotedCount?: number; commercialCount?: number; publishedCount?:number; engagementRate?: number; cpm?: number; cpr?: number; cpe?: number; supplier: Record<string, number>; actions: Record<string, number> }; analytics: Analytics; keyComments: KeyComment[]; notes: Note[]; ads?: Ads; syncedAt: string };
type AdsAccount = { account:string; brand:string; metricDate:string; spend:number; impressions:number; clicks:number; ctr:number; interactions:number; balance:number };
type AdsTotals = { accounts?:number; spend?:number; impressions?:number; clicks?:number; interactions?:number; ctr?:number };
type Ads = { totals:AdsTotals; accounts:AdsAccount[] };
type Job = { id: string; type: string; title: string; status: string; progress: number; total: number; succeeded: number; failed: number; message: string; createdAt: string; finishedAt?: string };
type SupplierRow = { id: number; noteId: string; noteUrl: string; creator: string; plannedContent: string; commentFormat: string; visibility: string; matchedContent?: string; verifiedAt?: string };
type Feature = { visibility: string; count: number; avgLength: number; commaRate: number; detailRate: number };
type ReviewRule={id:string;name:string;keywords:string;sentiment:string;category:string;action:string;priority:number;enabled:number;updatedAt:string};
type SavedReport={id:string;title:string;periodStart?:string;periodEnd?:string;status:string;summaryJson:string;createdAt:string;updatedAt:string};
type Rules = { brands:string[];competitors:string[];positiveWords:string[];negativeWords:string[];questionWords?:string[];sellingWords?:string[];irrelevantWords?:string[];deleteCompetitorMentions?:boolean };
type Acceptance = { reportCount:number;baseCount:number;brandTopRate:number;freshnessHours?:number;supplierSimilarity?:number };
type Goals = { workTarget:number;workCompleted:number;publishTarget:number;budgetTarget:number;commentTarget:number };
type GrowthKeyword = { id:string;keyword:string;scope:string;source:string;status:string;priority:number };
type GrowthInspiration = { id:string;title:string;keyword:string;stage:string;reason:string;sourceNoteId?:string;sourceType:string;owner?:string };
type GrowthSettings = { watchKeywords:GrowthKeyword[];inspirations:GrowthInspiration[];seedNoteIds:string[];thresholds:{breakoutInteractions:number;seedScore:number;ctr:number;cpuv:number} };
type Ops = { jobs: Job[]; logs: Array<{ id: number; action: string; targetType: string; targetId: string; detail: string; createdAt: string }>; supplier: SupplierRow[]; supplierFeatures: Feature[]; categories: Array<{ category: string; sentiment: string; count: number }>; reviewRules:ReviewRule[];reports:SavedReport[]; settings: { rules: Rules; acceptance: Acceptance; goals:Goals;growth:GrowthSettings } };
type NoteDetail = { note?: Note; snapshots: Array<{ capturedAt: string; l1Count: number; l2Count: number; totalCount: number; positiveCount: number; negativeCount: number; questionCount: number }>; comments: KeyComment[] };
type Project = { id:string;name:string;spu:string;brand:string;category:string;description:string;status:string;color:string;startAt?:string;endAt?:string;updatedAt:string;noteCount:number;reportableCount:number };
type DataSource = { id:string;projectId:string;type:string;name:string;spreadsheet:string;sheetId:string;range:string;kind:'owned'|'supplier';syncFrequency:string;status:string;lastSyncedAt?:string;lastRowCount:number;updatedAt:string };
type Workspace = { projects:Project[];sources:DataSource[] };

const emptyAnalytics: Analytics = { trend: [], sourceDistribution: [], scopeDistribution: [], statusDistribution: [], topics: [], brands: [], formats: [], creatorLevels: [], categories: [], locations: [], dataQuality: {}, topNotes: [] };
const fallback: Dashboard = { pipelines: [{ id: 'viral', name: '素人评论大爆文', targetCount: 200, deliveredCount: 128, budget: 24000, spent: 15360 }, { id: 'value_scan', name: '价值笔记扫描', targetCount: 68, deliveredCount: 43, budget: 12000, spent: 7200 }, { id: 'commercial', name: '新发商业笔记', targetCount: 360, deliveredCount: 276, budget: 42000, spent: 30660 }], metrics: { noteCount: 0, commentTotal: 0, positiveCount: 0, positiveRate: 0, negativeCount: 0, negativeRate: 0, questionCount: 0, questionRate: 0, supplier: {}, actions: {} }, analytics: emptyAnalytics, keyComments: [], notes: [], ads: { totals: {}, accounts: [] }, syncedAt: '' };
const emptyOps: Ops = { jobs: [], logs: [], supplier: [], supplierFeatures: [], categories: [],reviewRules:[],reports:[], settings: { rules: { brands: ['飞鹤', '启萃', '卓睿'], competitors: ['爱他美', '合生元', '派星', 'A2', '至初', '美素', '金领冠'], positiveWords: ['好吸收', '长肉', '适应', '抵抗力'], negativeWords: ['不好', '过敏', '便秘', '胀气', '吐奶'],questionWords:['吗','怎么','多少'],sellingWords:['出售','加微'],irrelevantWords:['互赞','打卡'],deleteCompetitorMentions:true }, acceptance: { reportCount: 200, baseCount: 30, brandTopRate: .4,freshnessHours:24,supplierSimilarity:.58 }, goals:{workTarget:0,workCompleted:0,publishTarget:0,budgetTarget:0,commentTarget:0},growth:{watchKeywords:[],inspirations:[],seedNoteIds:[],thresholds:{breakoutInteractions:1000,seedScore:65,ctr:.15,cpuv:.7}} } };
const fallbackProject:Project={id:'qicui',name:'启萃评论与声量项目',spu:'启萃',brand:'飞鹤',category:'婴幼儿奶粉',description:'评论执行、口碑舆情与本竞品监测',status:'进行中',color:'#1769d5',updatedAt:'',noteCount:0,reportableCount:0};
const nav = [
  ['cockpit', '今日工作台',''],
  ['growth', '增长机会','growth'],
  ['content', '内容与发布','content'],
  ['acceptance', '评论验收','acceptance'],
  ['risk', '舆情处置','risk'],
  ['insights', '分析与复盘','insights'],
  ['settings', '项目设置','settings'],
] as const;
const sectionAliases:Record<string,string>={voice:'insights',competitor:'insights',reports:'insights',progress:'acceptance',supplier:'acceptance',sentiment:'risk',notes:'content',tasks:'cockpit',radar:'growth',inspiration:'growth',seeds:'growth'};
const pct = (value: number) => `${(Number(value || 0) * 100).toFixed(1)}%`;
const cnTime = (value?: string) => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '—';
const daysAgo = (days: number) => { const d = new Date(); d.setDate(d.getDate() - days); return d.toISOString().slice(0, 10); };
const num = (value: unknown) => Number(value || 0);
const compact = (value: unknown) => new Intl.NumberFormat('zh-CN', { notation: 'compact', maximumFractionDigits: 1 }).format(num(value));
async function api<T>(path: string, options?: RequestInit): Promise<T> { const response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(options?.headers || {}) } }); const data = await response.json() as T & { ok?: boolean; error?: string }; if (!response.ok || data.ok === false) throw new Error(data.error || '操作失败'); return data as T; }

export default function DashboardClient({ userName, signedIn, initialProjectId='qicui', initialSection='cockpit' }: { userName: string; signedIn: boolean; initialProjectId?:string;initialSection?:string }) {
  const [active, setActive] = useState(sectionAliases[initialSection] || initialSection); const [data, setData] = useState<Dashboard>(fallback); const [ops, setOps] = useState<Ops>(emptyOps); const [workspace,setWorkspace]=useState<Workspace>({projects:[fallbackProject],sources:[]}); const [projectId]=useState(initialProjectId);
  const [loading, setLoading] = useState(false); const [toast, setToast] = useState(''); const [runResult, setRunResult] = useState('');
  const [noteIds, setNoteIds] = useState(''); const [keywords, setKeywords] = useState('启萃,飞鹤奶粉');
  const [from, setFrom] = useState(daysAgo(90)); const [to, setTo] = useState(new Date().toISOString().slice(0, 10)); const [source, setSource] = useState(''); const [detail, setDetail] = useState<NoteDetail | null>(null);
  const title = nav.find(([id]) => id === active)?.[1] || '今日工作台';
  const currentProject=workspace.projects.find(x=>x.id===projectId)||fallbackProject;
  const switchProject=(id:string)=>{window.location.assign(`/projects/${id}`)};
  const openSection=(id:string)=>{const target=sectionAliases[id]||id;setActive(target);const item=nav.find(([key])=>key===target);if(typeof window!=='undefined'){const nextUrl=`/projects/${projectId}/${item?.[2]||''}`;if(window.location.pathname!==nextUrl)window.history.pushState(null,'',nextUrl)}};
  const refresh = useCallback(async () => { const query = new URLSearchParams({ from,to,projectId }); if (source) query.set('source', source); const [dashboard,operations,projects] = await Promise.all([api<Dashboard>(`/api/dashboard?${query}`),api<Ops>(`/api/ops?projectId=${encodeURIComponent(projectId)}`),api<Workspace>('/api/projects')]); setData(dashboard);setOps(operations);setWorkspace(projects); }, [from,to,source,projectId]);
  useEffect(() => { const timer = setTimeout(() => { refresh().catch(() => undefined) }, 0); return () => clearTimeout(timer) }, [refresh]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 3200); return () => clearTimeout(timer); }, [toast]);
  async function task<T>(work: () => Promise<T>, success: string) { setLoading(true); setRunResult(''); try { const value = await work(); setToast(success); await refresh(); return value; } catch (error) { setToast(error instanceof Error ? error.message : '操作失败'); throw error; } finally { setLoading(false); } }
  async function runFetch(ids = noteIds) { try { const result = await task(() => api<{ results: Array<Record<string, unknown>> }>('/api/comments/fetch', { method:'POST',body:JSON.stringify({noteIds:ids,projectId}) }), '全量评论抓取与增量比对完成'); setRunResult(result.results.map((x) => x.ok ? `${x.noteId}：主评论 ${x.fetchedL1}，楼中楼 ${x.fetchedL2}，合计 ${x.total}，${x.status}` : `${x.noteId}：失败 · ${x.error}`).join('\n')); } catch { /* toast handles */ } }
  async function runSearch() { try { const result = await task(() => api<{ count: number }>('/api/notes/search', { method:'POST',body:JSON.stringify({keywords,startDate:from,endDate:to,maxPages:5,projectId}) }), '关键词扫描完成'); setRunResult(`已扫描并入库 ${result.count} 篇笔记，可在内容池中筛选并批量抓取。`); } catch { /* toast handles */ } }
  async function uploadWorkbook(file: File | undefined, kind: 'owned' | 'supplier') { if (!file) return; try { await task(async () => { if (!window.XLSX) throw new Error('Excel 解析组件尚未加载'); const book = window.XLSX.read(await file.arrayBuffer()); const rows = window.XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]], { defval: '' }); const result = await api<{ imported: number; skipped: number }>('/api/import', { method:'POST',body:JSON.stringify({kind,rows,projectId}) }); setRunResult(`导入 ${result.imported} 条，跳过 ${result.skipped} 条。`); return result; }, '表格导入完成'); } catch { /* toast handles */ } }
  async function verifySupplier() { try { const result = await task(() => api<{ summary: { exact: number; modified: number; missing: number; failedNotes: number } }>('/api/supplier/verify', { method:'POST',body:JSON.stringify({projectId}) }), '供应商外显核验完成'); setRunResult(`原文一致 ${result.summary.exact}，有修改 ${result.summary.modified}，未外显 ${result.summary.missing}，失败笔记 ${result.summary.failedNotes}。`); } catch { /* toast handles */ } }
  async function resolveComment(item: KeyComment, method: string) { try { await task(() => api('/api/actions', { method:'POST',body:JSON.stringify({id:item.id,status:'已处理',method,projectId}) }), '处置状态已更新'); } catch { /* toast handles */ } }
  async function resource(action:string,payload:Record<string,unknown>={},success='已保存'){try{await task(()=>api('/api/resources',{method:'POST',body:JSON.stringify({action,projectId,...payload})}),success)}catch{/* toast handles */}}
  async function removeComment(item:KeyComment){if(confirm('确认从关键评论清单移除此记录？'))await resource('comment_delete',{id:item.id},'关键评论已移除')}
  async function saveNote(note:Note){await resource('note_update',note as unknown as Record<string,unknown>,'笔记资料已更新');setDetail(null)}
  async function removeNote(note:Note){if(confirm('确认将此笔记及当前项目内的评论快照移出项目？')){await resource('note_delete',{id:note.id},'笔记已移出当前项目');setDetail(null)}}
  async function openNote(id: string) { try { setDetail(await api<NoteDetail>(`/api/notes/detail?id=${id}&projectId=${encodeURIComponent(projectId)}`)); } catch (error) { setToast(error instanceof Error ? error.message : '明细加载失败'); } }
  const pending=num(data.metrics.actions.replyPending)+num(data.metrics.actions.deletePending);
  const showFilters=active==='growth'||active==='content'||active==='insights';
  const primaryAction=active==='cockpit'?{label:'处理今日待办',run:()=>openSection(pending?'risk':'acceptance')}:active==='growth'?{label:'配置观察关键词',run:()=>document.getElementById('growth-keywords')?.scrollIntoView({behavior:'smooth'})}:active==='content'?{label:'添加或更新数据',run:()=>document.getElementById('content-entry')?.scrollIntoView({behavior:'smooth'})}:active==='acceptance'?{label:'处理待验收批次',run:()=>document.getElementById('acceptance-workspace')?.scrollIntoView({behavior:'smooth'})}:active==='risk'?{label:'处理风险评论',run:()=>document.getElementById('risk-list')?.scrollIntoView({behavior:'smooth'})}:active==='insights'?{label:'生成项目复盘',run:()=>window.dispatchEvent(new CustomEvent('open-insight-report'))}:null;
  return <div className="app-shell">
    <aside className="sidebar">
      <button className="back-platform" onClick={()=>window.location.assign('/')}>← 返回项目中心</button>
      <div className="brand"><span>智</span><div>社媒增长中台<small>PROJECT WORKSPACE</small></div></div>
      <div className="project-switcher"><small>当前项目</small><div><i style={{background:currentProject.color}}/><select value={projectId} onChange={(e)=>switchProject(e.target.value)}>{workspace.projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></div><p>{currentProject.brand} · {currentProject.spu} · {currentProject.status}</p></div>
      <div className="workspace-shortcuts"><button onClick={()=>window.location.assign(`/projects/${projectId}/agent`)}><b>AI</b><span>智能看板<small>自然语言生成报告</small></span></button><button onClick={()=>window.location.assign(`/projects/${projectId}/data-map`)}><b>DM</b><span>数据地图<small>账户·接口·指标口径</small></span></button></div>
      <nav aria-label="项目导航">{nav.map(([id,label],index)=><button key={id} className={active===id?'active':''} onClick={()=>openSection(id)}><span>{String(index+1).padStart(2,'0')}</span>{label}</button>)}</nav>
      <div className="sidebar-guide"><small>业务闭环</small><p>增长机会 → 内容发布 → 评论验收 → 舆情处置 → 分析复盘</p></div>
      <div className="sidebar-foot"><i /> 项目数据与任务服务正常<br/><small>{userName} · {signedIn?'已登录':'本地预览'} · {cnTime(data.syncedAt)}</small></div>
    </aside>
    <main className="main">
      <header className="topbar"><div><p>{currentProject.name} · {currentProject.brand||'未配置品牌'} / {currentProject.spu}</p><h1>{title}</h1></div><div className="range-actions">{showFilters&&<><label>从<input type="date" value={from} onChange={(e)=>setFrom(e.target.value)}/></label><label>至<input type="date" value={to} onChange={(e)=>setTo(e.target.value)}/></label><select value={source} onChange={(e)=>setSource(e.target.value)}><option value="">全部来源</option><option value="owned">自有笔记</option><option value="keyword_scan">关键词扫描</option></select></>}{primaryAction&&<button className="primary" onClick={primaryAction.run}>{primaryAction.label}</button>}</div></header>
      <WorkflowRibbon active={active}/>
      {active==='cockpit'&&<TodayWorkspace data={data} ops={ops} loading={loading} onDone={refresh} toast={setToast} projectId={projectId} setActive={openSection} openNote={openNote}/>}
      {active==='growth'&&<GrowthWorkspace data={data} ops={ops} projectId={projectId} onDone={refresh} toast={setToast} openNote={openNote}/>}
      {active==='content'&&<ContentWorkspaceV2 data={data} noteIds={noteIds} setNoteIds={setNoteIds} keywords={keywords} setKeywords={setKeywords} from={from} to={to} runFetch={runFetch} runSearch={runSearch} uploadWorkbook={uploadWorkbook} loading={loading} runResult={runResult} openNote={openNote}/>}
      {active==='acceptance'&&<AcceptanceWorkspace data={data} ops={ops} uploadWorkbook={uploadWorkbook} verifySupplier={verifySupplier} loading={loading} runResult={runResult} projectId={projectId} onDone={refresh} toast={setToast}/>}
      {active==='risk'&&<section id="risk-list"><Triage comments={data.keyComments} resolveComment={resolveComment} removeComment={removeComment} projectId={projectId}/></section>}
      {active==='insights'&&<InsightsWorkspace data={data} project={currentProject} ops={ops} projectId={projectId} onDone={refresh} toast={setToast} openNote={openNote} setActive={openSection}/>}
      {active==='settings'&&<><SettingsWorkspace data={data} ops={ops} loading={loading} onDone={refresh} toast={setToast} projectId={projectId}/><div id="project-totals"><ProjectGoalsSettings data={data} goals={ops.settings.goals} loading={loading} onDone={refresh} toast={setToast} projectId={projectId}/></div></>}
    </main>
    {detail&&<DetailDrawer key={detail.note?.id||'detail'} detail={detail} close={()=>setDetail(null)} saveNote={saveNote} removeNote={removeNote}/>} {loading&&<div className="busy" role="status"><span/>任务执行中，完成后会自动刷新…</div>} {toast&&<div className="toast">{toast}</div>}
  </div>;
}

function WorkflowRibbon({active}:{active:string}) {
  const steps=[['growth','发现机会'],['content','内容发布'],['acceptance','评论验收'],['risk','舆情处置'],['insights','分析复盘']];
  return <section className="workflow-ribbon" aria-label="项目业务闭环"><div><small>PROJECT LOOP</small><strong>项目业务闭环</strong></div>{steps.map(([id,label],index)=><span key={id} className={active===id?'active':active==='cockpit'?'ready':''}><i>{index+1}</i>{label}</span>)}</section>
}

function SectionTabs({items,value,onChange}:{items:Array<[string,string,string]>;value:string;onChange:(value:string)=>void}) {
  return <div className="section-tabs" role="tablist">{items.map(([id,label,copy])=><button key={id} role="tab" aria-selected={value===id} className={value===id?'active':''} onClick={()=>onChange(id)}><strong>{label}</strong><small>{copy}</small></button>)}</div>
}

function TodayWorkspace({data,ops,loading,onDone,toast,projectId,setActive,openNote}:{data:Dashboard;ops:Ops;loading:boolean;onDone:()=>Promise<void>;toast:(v:string)=>void;projectId:string;setActive:(id:string)=>void;openNote:(id:string)=>void}) {
  const [view,setView]=useState('overview');
  return <div className="stack">
    <section className="page-intro"><div><small>PROJECT COMMAND CENTER</small><h2>项目经营驾驶舱</h2><p>先判断总盘完成度，再查看执行、口碑、内容与风险明细；所有指标都能追溯到业务页面。</p></div><b>{num(data.metrics.actions.replyPending)+num(data.metrics.actions.deletePending)}<span>条风险待办</span></b></section>
    <GoalProgressGrid data={data} goals={ops.settings.goals} onConfigure={()=>window.location.assign(`/projects/${projectId}/settings#project-totals`)}/>
    <GrowthOpportunitySummary data={data} growth={ops.settings.growth} openGrowth={()=>setActive('growth')}/>
    <SectionTabs value={view} onChange={setView} items={[["overview","经营总览","目标、趋势与关键结论"],["execution","执行监控","主线、费用与处置进度"],["report","数据报告","多维结构与表现明细"],["tasks","任务记录","临时任务与执行日志"]]}/>
    {view==='overview'&&<Overview data={data} setActive={setActive} openNote={openNote}/>}
    {view==='execution'&&<ExecutionDashboard data={data} ops={ops}/>}
    {view==='report'&&<DetailedDataReport data={data}/>}
    {view==='tasks'&&<Tasks ops={ops} loading={loading} onDone={onDone} toast={toast} projectId={projectId}/>}
  </div>
}

function goalRate(actual:number,target:number){return target>0?actual/target:0}
function GoalProgressGrid({data,goals,onConfigure}:{data:Dashboard;goals:Goals;onConfigure:()=>void}){
  const spent=data.pipelines.reduce((sum,row)=>sum+num(row.spent),0);
  const delivered=data.pipelines.reduce((sum,row)=>sum+num(row.deliveredCount),0);
  const budgetTarget=num(goals.budgetTarget)||data.pipelines.reduce((sum,row)=>sum+num(row.budget),0);
  const commentTarget=num(goals.commentTarget)||data.pipelines.reduce((sum,row)=>sum+num(row.targetCount),0);
  const cards=[
    {label:'项目进度',actual:num(goals.workCompleted),target:num(goals.workTarget),unit:'项',note:'项目任务总盘'},
    {label:'消耗进度',actual:spent,target:budgetTarget,unit:'元',note:goals.budgetTarget?'项目总预算':'按主线预算合计'},
    {label:'发布进度',actual:num(data.metrics.publishedCount),target:num(goals.publishTarget),unit:'篇',note:'已发布笔记'},
    {label:'评论交付',actual:delivered,target:commentTarget,unit:'条',note:goals.commentTarget?'项目评论总目标':'按主线目标合计'},
  ];
  return <section className="goal-progress-section"><div className="goal-progress-head"><div><small>PROJECT TOTALS</small><strong>项目总盘完成度</strong><span>首页进度统一使用项目设置中的总目标</span></div><button onClick={onConfigure}>配置总目标 →</button></div><div className="goal-progress-grid">{cards.map((card,index)=>{const rate=goalRate(card.actual,card.target);return <article key={card.label} className={`goal-progress-card tone-${index+1}`}><div><span>{card.label}</span><i>{card.target?`${Math.round(rate*100)}%`:'待设置'}</i></div><strong>{card.unit==='元'?`¥${compact(card.actual)}`:compact(card.actual)}<small> / {card.target?(card.unit==='元'?`¥${compact(card.target)}`:`${compact(card.target)} ${card.unit}`):'未设置目标'}</small></strong><div className="goal-progress-track"><i style={{width:`${Math.min(100,rate*100)}%`}}/></div><p>{card.note}{rate>1?` · 超出目标 ${Math.round((rate-1)*100)}%`:card.target?` · 尚余 ${compact(Math.max(0,card.target-card.actual))}${card.unit}`:' · 请在项目设置中补充'}</p></article>})}</div></section>
}

function ExecutionDashboard({data,ops}:{data:Dashboard;ops:Ops}){
  const supplier=data.metrics.supplier||{};const actions=data.metrics.actions||{};
  const supplierTotal=Math.max(1,num(supplier.total));const actionTotal=Math.max(1,num(actions.total));const acceptance=ops.settings.acceptance;
  const adsTotals=(data.ads&&data.ads.totals)||{};const adsAccounts=(data.ads&&data.ads.accounts)||[];
  return <div className="report-grid">
    <ReportTable wide eyebrow="DELIVERY LINES" title="三条主线执行明细" headers={['执行主线','评论进度','完成率','费用进度','消耗率','剩余交付']} rows={data.pipelines.map(row=>[row.name,`${row.deliveredCount} / ${row.targetCount}`,pct(row.targetCount?row.deliveredCount/row.targetCount:0),`¥${row.spent.toLocaleString()} / ¥${row.budget.toLocaleString()}`,pct(row.budget?row.spent/row.budget:0),`${Math.max(0,row.targetCount-row.deliveredCount)} 条`])}/>
    <ReportTable eyebrow="SUPPLIER QA" title="供应商外显结构" headers={['状态','数量','占比']} rows={[["原文一致",num(supplier.exactCount),pct(num(supplier.exactCount)/supplierTotal)],["有修改外显",num(supplier.modifiedCount),pct(num(supplier.modifiedCount)/supplierTotal)],["当前未外显",num(supplier.missingCount),pct(num(supplier.missingCount)/supplierTotal)],["待核验",num(supplier.pendingCount),pct(num(supplier.pendingCount)/supplierTotal)]]}/>
    <ReportTable eyebrow="RISK SLA" title="风险处置进度" headers={['处理状态','数量','占全部风险']} rows={[["已处理",num(actions.handled),pct(num(actions.handled)/actionTotal)],["待达人回复",num(actions.replyPending),pct(num(actions.replyPending)/actionTotal)],["待删除",num(actions.deletePending),pct(num(actions.deletePending)/actionTotal)],["已消失",num(actions.disappeared),pct(num(actions.disappeared)/actionTotal)]]}/>
    <ReportTable eyebrow="ACCEPTANCE RULES" title="当前项目验收口径" headers={['规则','阈值','业务含义']} rows={[["可汇报评论数",`${acceptance.reportCount} 条`,'达到高质量汇报门槛'],["基础达标评论数",`${acceptance.baseCount} 条`,'进入基础验收状态'],["前三屏产品提及率",pct(acceptance.brandTopRate),'判断品牌有效露出'],["数据新鲜度",`${acceptance.freshnessHours||24} 小时`,'超过后提示重新抓取'],["供应商相似度",pct(acceptance.supplierSimilarity||.58),'识别原文一致或修改外显']]}/>
    <ReportTable eyebrow="CONTENT STATUS" title="笔记验收分布" headers={['验收状态','笔记数','占比']} rows={data.analytics.statusDistribution.map(row=>[String(row.name||'未分类'),num(row.count),pct(num(row.count)/Math.max(1,data.metrics.noteCount))])}/>
    <ReportTable wide eyebrow="JUGUANG PAID" title="聚光投放账户（导入数据）" headers={['子账户','品牌','数据日期','消耗','曝光','点击','CTR','互动','余额']} rows={adsAccounts.length?adsAccounts.map(row=>[String(row.account),String(row.brand||'—'),String(row.metricDate),`¥${num(row.spend).toLocaleString()}`,compact(row.impressions),compact(row.clicks),pct(num(row.ctr)),compact(row.interactions),`¥${num(row.balance).toLocaleString()}`]):[['—','—','—','—','—','—','—','—','—']]}/>
    {adsTotals.accounts? <p className="data-note">聚光汇总：{num(adsTotals.accounts)} 个账户 · 消耗 ¥{num(adsTotals.spend).toLocaleString()} · CTR {pct(num(adsTotals.ctr))}（数据来自 partner 后台导入，可在数据源页更新）</p> : null}
  </div>
}

